/**
* Save imported dishes and ingredients and share them with every device.
* Existing dishes with the same id are replaced; with `removeOthers`, dishes
* not in the import are deleted (past bills keep their copies).
*/
async function applyMenuImport(items, materials, options = {}) {
	const db = getDb();
	const keep = new Set(items.map((i) => i.id));
	const changes = [];
	let removed = 0;
	await db.transaction("rw", db.menu, db.materials, async () => {
		if (materials.length) await db.materials.bulkPut(materials);
		if (items.length) await db.menu.bulkPut(items);
		if (options.removeOthers) {
			const stale = (await db.menu.toCollection().primaryKeys()).map(String).filter((id) => !keep.has(id));
			if (stale.length) await db.menu.bulkDelete(stale);
			removed = stale.length;
			changes.push(...stale.map((id) => ["menu", id]));
		}
	});
	changes.push(...materials.map((m) => ["material", m.id]), ...items.map((i) => ["menu", i.id]));
	await markDirty(...changes);
	return {
		dishes: items.length,
		ingredients: materials.length,
		removed
	};
}
/** Loads the TAB Bistro by XTSY menu, ingredients and recipes (kept in a separate chunk until needed). */
async function loadTabBistroMenu(removeOthers) {
	const { TAB_MATERIALS, TAB_MENU } = await import("./tab-bistro-BIGlMzB4.js");
	const db = getDb();
	const current = new Map((await db.materials.toArray()).map((m) => [m.id, m]));
	const result = await applyMenuImport(TAB_MENU, TAB_MATERIALS.map((m) => {
		const mine = current.get(m.id);
		return mine ? {
			...m,
			...mine.costPerUnit !== void 0 ? { costPerUnit: mine.costPerUnit } : {},
			lowStockLevel: mine.lowStockLevel
		} : m;
	}), { removeOthers });
	const { TAB_CATEGORIES } = await import("./tab-bistro-BIGlMzB4.js");
	const settings = await getSettings();
	await saveSettings({
		...settings,
		name: settings.name || "TAB Bistro by XTSY",
		categoryOrder: TAB_CATEGORIES
	});
	return result;
}
